def summarise(runs, threshold):
    stats = {}
    for attack, owasp, ok in runs:
        s = stats.setdefault(attack, {'attack': attack, 'owasp': owasp, 'runs': 0, 'successes': 0})
        s['runs'] += 1
        s['successes'] += 1 if ok else 0
    out = []
    for s in stats.values():
        s['rate'] = round(s['successes'] / s['runs'], 2)
        if s['rate'] >= threshold:
            out.append(s)
    return sorted(out, key=lambda s: (-s['rate'], s['attack']))

import re

def disallowed_links(output, allowed_domains):
    bad = []
    for host in re.findall(r'https?://([^/:?#\s]+)', output, flags=re.IGNORECASE):
        host = host.lower()
        ok = any(host == d or host.endswith('.' + d) for d in allowed_domains)
        if not ok and host not in bad:
            bad.append(host)
    return bad
